    sol: "server {\n  listen 80;\n  server_name example.com;\n\n  location /api/ {\n    proxy_pass http://127.0.0.1:4000/;\n    proxy_set_header Host $host;\n    proxy_set_header X-Real-IP $remote_addr;\n  }\n\n  location / {\n    root /var/www/myapp/dist;\n    try_files $uri $uri/ /index.html;\n  }\n}",
    exp: "try_files ... /index.html is the standard SPA fallback so client-side routes (e.g. /profile) don't 404 on a hard refresh; proxy_set_header forwards the real client IP/host to the backend, which otherwise only sees Nginx's own address.",
